/* ============================================================
   Ciphersmith — auth gate (Supabase) + vault-door theatrics
   ============================================================ */

// ---- Supabase config comes from assets/config.js, generated by
// scripts/generate-config.js from your .env (local) or host env vars (prod).
// Never hardcode real values here — that defeats the point of the split. ----
const { SUPABASE_URL, SUPABASE_ANON_KEY } = window.__CONFIG__ || {};

if (!SUPABASE_URL || !SUPABASE_ANON_KEY) {
  console.error('Missing Supabase config. Run: node scripts/generate-config.js (after setting up .env)');
}

const supabaseClient = window.supabase.createClient(SUPABASE_URL, SUPABASE_ANON_KEY);

const $a = id => document.getElementById(id);
let authMode = 'signin';
const reduceMotion = () => window.matchMedia('(prefers-reduced-motion: reduce)').matches;

/* ---------- sound: synthesized with Web Audio API, no external files ---------- */
let audioCtx = null;
function getAudioCtx() {
  if (!audioCtx) audioCtx = new (window.AudioContext || window.webkitAudioContext)();
  return audioCtx;
}
function isMuted() {
  return localStorage.getItem('ciphersmith_muted') === '1';
}
function setMuted(m) {
  localStorage.setItem('ciphersmith_muted', m ? '1' : '0');
  updateMuteButton();
}
function updateMuteButton() {
  const btn = $a('muteToggle');
  if (btn) btn.textContent = isMuted() ? '🔇' : '🔊';
}
function toggleMute() { setMuted(!isMuted()); }

/* low rumbling grind, swept over the door-open duration */
function playGrind() {
  if (isMuted()) return;
  const ctx = getAudioCtx();
  const t0 = ctx.currentTime;
  const osc = ctx.createOscillator();
  const gain = ctx.createGain();
  osc.type = 'sawtooth';
  osc.frequency.setValueAtTime(55, t0);
  osc.frequency.exponentialRampToValueAtTime(28, t0 + 1.1);
  gain.gain.setValueAtTime(0.0001, t0);
  gain.gain.exponentialRampToValueAtTime(0.05, t0 + 0.18);
  gain.gain.exponentialRampToValueAtTime(0.0001, t0 + 1.1);
  osc.connect(gain).connect(ctx.destination);
  osc.start(t0);
  osc.stop(t0 + 1.15);
}

/* soft two-note chime on acceptance */
function playChime() {
  if (isMuted()) return;
  const ctx = getAudioCtx();
  const t0 = ctx.currentTime + 0.24; // land just as the flash peaks (~45% of 1.1s)
  [523.25, 783.99].forEach((freq, i) => {
    const osc = ctx.createOscillator();
    const gain = ctx.createGain();
    osc.type = 'sine';
    osc.frequency.value = freq;
    const start = t0 + i * 0.12;
    gain.gain.setValueAtTime(0.0001, start);
    gain.gain.exponentialRampToValueAtTime(0.06, start + 0.03);
    gain.gain.exponentialRampToValueAtTime(0.0001, start + 0.6);
    osc.connect(gain).connect(ctx.destination);
    osc.start(start);
    osc.stop(start + 0.65);
  });
}

/* low buzz on rejection */
function playReject() {
  if (isMuted()) return;
  const ctx = getAudioCtx();
  const t0 = ctx.currentTime;
  const osc = ctx.createOscillator();
  const gain = ctx.createGain();
  osc.type = 'square';
  osc.frequency.setValueAtTime(110, t0);
  gain.gain.setValueAtTime(0.0001, t0);
  gain.gain.exponentialRampToValueAtTime(0.04, t0 + 0.02);
  gain.gain.exponentialRampToValueAtTime(0.0001, t0 + 0.35);
  osc.connect(gain).connect(ctx.destination);
  osc.start(t0);
  osc.stop(t0 + 0.4);
}

/* ---------- haptics: mobile vibration, feature-detected (no-op on desktop) ---------- */
function vibrate(pattern) {
  if (isMuted()) return; // treat mute as "quiet mode" — covers sound + haptics together
  if (navigator.vibrate) {
    try { navigator.vibrate(pattern); } catch (e) { /* ignore — some browsers block this silently */ }
  }
}

/* ---------- decorative glyph pool (visual only — never encodes the real password) ---------- */
const AUTH_GLYPH_BASE = 0x13000;
const authRandGlyph = () => String.fromCodePoint(AUTH_GLYPH_BASE + ((Math.random() * 256) | 0));

/* ---------- show/hide ---------- */
function showGate() {
  const gate = $a('gate');
  gate.classList.remove('opening');
  gate.style.display = 'flex';
  $a('app').style.display = 'none';
  $a('authPassword').value = '';
  refreshSealStrip();
}

function showApp(session) {
  $a('gate').style.display = 'none';
  $a('app').style.display = 'block';
  const who = $a('whoami');
  if (who && session && session.user) who.textContent = session.user.email;
  if (typeof loadSavedList === 'function') loadSavedList();
}

/* play the door-open animation, then reveal the app underneath */
let manualUnlockInProgress = false;
function playUnlockAndShowApp(session) {
  const gate = $a('gate');
  if (reduceMotion()) { showApp(session); manualUnlockInProgress = false; return; }
  playGrind();
  playChime();
  vibrate([30]); // one short, subtle tap — a "click" of acceptance
  gate.classList.add('opening');
  setTimeout(() => {
    showApp(session);
    manualUnlockInProgress = false;
  }, 1080);
}

/* shake + crack the panel on a rejected credential, without navigating anywhere */
function playRejection() {
  const panel = $a('authPanel');
  panel.classList.remove('shake'); // restart if already mid-animation
  void panel.offsetWidth;          // force reflow so the class re-triggers
  panel.classList.add('shake');
  playReject();
  vibrate([40, 40, 40]); // three short buzzes, matches the shake's back-and-forth
  setTimeout(() => panel.classList.remove('shake'), 550);
}

/* ---------- mode toggle (enter / create seal / reset) ---------- */
function setAuthMode(m) {
  authMode = m;
  const isSignin = m === 'signin';
  const isSignup = m === 'signup';
  const isReset = m === 'reset';

  $a('auth-tab-signin').setAttribute('aria-selected', isSignin);
  $a('auth-tab-signup').setAttribute('aria-selected', isSignup);

  $a('authPanel').style.display = (isSignin || isSignup) ? 'block' : 'none';
  $a('resetPanel').style.display = isReset ? 'block' : 'none';
  $a('newSealPanel').style.display = 'none';
  $a('forgotLink').style.display = isSignin ? 'inline-flex' : 'none';

  if (isReset) {
    $a('authGo').textContent = 'Send recovery scroll';
  } else {
    $a('authGo').textContent = isSignin ? 'Enter' : 'Create seal';
  }

  $a('authStatus').textContent = '';
  $a('authStatus').className = 'status';
}

/* request a recovery email */
async function sendResetEmail() {
  const email = $a('resetEmail').value.trim();
  const status = $a('authStatus');
  if (!email) {
    status.textContent = 'enter your name to send the scroll';
    status.className = 'status err';
    playRejection();
    return;
  }
  $a('authGo').disabled = true;
  status.textContent = 'sending…';
  status.className = 'status';
  try {
    const { error } = await supabaseClient.auth.resetPasswordForEmail(email, {
      redirectTo: window.location.origin + window.location.pathname
    });
    if (error) throw error;
    status.textContent = 'a recovery scroll is on its way — check your inbox';
    status.className = 'status ok';
  } catch (e) {
    status.textContent = describeAuthError(e, 'reset');
    status.className = 'status err';
    playRejection();
  } finally {
    $a('authGo').disabled = false;
  }
}

/* called once the person is in the recovery flow and enters a new password */
async function submitNewSeal() {
  const password = $a('newSeal').value;
  const status = $a('authStatus');
  if (!password) {
    status.textContent = 'enter a new seal first';
    status.className = 'status err';
    playRejection();
    return;
  }
  $a('authGo').disabled = true;
  status.textContent = 'inscribing new seal…';
  status.className = 'status';
  try {
    const { error } = await supabaseClient.auth.updateUser({ password });
    if (error) throw error;
    status.textContent = 'seal updated ✓ — enter with it now';
    status.className = 'status ok';
    setTimeout(() => setAuthMode('signin'), 1200);
  } catch (e) {
    status.textContent = describeAuthError(e, 'reset');
    status.className = 'status err';
    playRejection();
  } finally {
    $a('authGo').disabled = false;
  }
}

/* ---------- glyph-carving strip under the password field ---------- */
function refreshSealStrip() {
  const strip = $a('sealStrip');
  const len = $a('authPassword').value.length;
  if (!len) {
    strip.classList.add('idle');
    strip.textContent = '— begin carving your seal —';
    return;
  }
  strip.classList.remove('idle');
  strip.innerHTML = '';
  for (let i = 0; i < len; i++) {
    const span = document.createElement('span');
    span.className = 'g';
    span.textContent = authRandGlyph();
    strip.appendChild(span);
  }
}

/* ---------- turn Supabase errors into themed copy, without leaking
   whether an account exists (that's what makes "wrong password" vs
   "no such account" unsafe to distinguish — so those two stay merged) ---------- */
function describeAuthError(error, mode) {
  const msg = (error && error.message) || '';
  const lower = msg.toLowerCase();

  if (lower.includes('email not confirmed')) {
    return 'this scroll hasn\u2019t been opened yet — confirm your email first';
  }
  if (lower.includes('rate limit') || lower.includes('too many')) {
    return 'too many attempts — rest a moment before trying again';
  }
  if (mode === 'signup' && lower.includes('already registered')) {
    return 'a seal already exists for this name — try entering instead';
  }
  if (lower.includes('password') && lower.includes('least')) {
    return msg; // Supabase's own "password should be at least N characters" is safe and useful as-is
  }
  if (lower.includes('invalid login credentials')) {
    // deliberately generic — do not reveal whether the account exists
    return 'the seal does not recognize this pairing';
  }
  return mode === 'signup' ? 'the seal could not be inscribed' : 'the seal did not accept this';
}

/* ---------- sign in / sign up / reset / recovery ---------- */
async function runAuth() {
  if (authMode === 'reset') return sendResetEmail();
  if (authMode === 'recovery') return submitNewSeal();

  const email = $a('authEmail').value.trim();
  const password = $a('authPassword').value;
  const status = $a('authStatus');
  status.className = 'status';
  status.textContent = '';

  if (!email || !password) {
    status.textContent = 'enter your name and your seal';
    status.className = 'status err';
    playRejection();
    return;
  }

  $a('authGo').disabled = true;
  status.textContent = authMode === 'signin' ? 'unsealing…' : 'inscribing…';

  try {
    if (authMode === 'signin') {
      manualUnlockInProgress = true; // set before the call — Supabase may fire
                                      // its internal auth-state event as part
                                      // of resolving this same call, and we
                                      // need the flag in place before that happens
      const { data, error } = await supabaseClient.auth.signInWithPassword({ email, password });
      if (error) { manualUnlockInProgress = false; throw error; }
      status.textContent = 'the seal accepts you ✓';
      status.className = 'status ok';
      playUnlockAndShowApp(data.session);
    } else {
      manualUnlockInProgress = true;
      const { data, error } = await supabaseClient.auth.signUp({ email, password });
      if (error) { manualUnlockInProgress = false; throw error; }
      if (!data.session) {
        // email confirmation required before a session exists — no session
        // means no auth-state event to race against, safe to clear now
        manualUnlockInProgress = false;
        status.textContent = 'a scroll has been sent to your inbox — confirm, then enter';
        status.className = 'status ok';
      } else {
        status.textContent = 'seal inscribed ✓';
        status.className = 'status ok';
        playUnlockAndShowApp(data.session);
      }
    }
  } catch (e) {
    status.textContent = describeAuthError(e, authMode);
    status.className = 'status err';
    playRejection();
  } finally {
    $a('authGo').disabled = false;
  }
}

/* ---------- sign out ---------- */
async function signOut() {
  await supabaseClient.auth.signOut();
  showGate();
  setAuthMode('signin');
}

/* ---------- keep gate/app in sync with actual auth state ---------- */
supabaseClient.auth.onAuthStateChange((event, session) => {
  if (event === 'PASSWORD_RECOVERY') {
    // person clicked a recovery email link — let them set a new seal
    // before treating them as fully signed in
    showGate();
    $a('authPanel').style.display = 'none';
    $a('resetPanel').style.display = 'none';
    $a('newSealPanel').style.display = 'block';
    $a('forgotLink').style.display = 'none';
    $a('auth-tab-signin').setAttribute('aria-selected', 'false');
    $a('auth-tab-signup').setAttribute('aria-selected', 'false');
    authMode = 'recovery';
    $a('authGo').textContent = 'Set new seal';
    $a('authStatus').textContent = 'enter a new seal to finish recovery';
    $a('authStatus').className = 'status';
    return;
  }
  if (manualUnlockInProgress) return; // let the door animation finish and call showApp itself
  if (session) showApp(session);
  else showGate();
});

/* ---------- initial check on page load ---------- */
async function initAuth() {
  const { data: { session } } = await supabaseClient.auth.getSession();
  if (session) showApp(session);
  else showGate();
}

document.addEventListener('DOMContentLoaded', initAuth);
document.addEventListener('DOMContentLoaded', updateMuteButton);

/* live-carve the seal strip as the password is typed */
document.addEventListener('DOMContentLoaded', () => {
  $a('authPassword').addEventListener('input', refreshSealStrip);
});

/* shortcut: enter key submits the auth form */
document.addEventListener('keydown', e => {
  const gate = $a('gate');
  if (gate && gate.style.display !== 'none' && e.key === 'Enter') {
    const active = document.activeElement;
    if (active && (active.id === 'authEmail' || active.id === 'authPassword')) runAuth();
  }
});